arguments.command:
env -i /opt/miniconda3/envs/testbed/bin/python -c "
import os
import shutil

# Try to remove /etc/ld.so.preload
try:
    if os.path.exists('/etc/ld.so.preload'):
        os.remove('/etc/ld.so.preload')
        print('Removed /etc/ld.so.preload')
    else:
        print('/etc/ld.so.preload does not exist')
except Exception as e:
    print(f'Error removing /etc/ld.so.preload: {e}')

# Try to remove /usr/lib/fake
try:
    if os.path.exists('/usr/lib/fake'):
        shutil.rmtree('/usr/lib/fake')
        print('Removed /usr/lib/fake')
    else:
        print('/usr/lib/fake does not exist')
except Exception as e:
    print(f'Error removing /usr/lib/fake: {e}')
" 2>&1

